begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) select ('40000000-0000-0000-0000-00000000000'||n)::uuid,'critical-sql-'||n||'@example.invalid',jsonb_build_object('username','CriticalSQL'||n) from generate_series(1,5) n;
insert into auth.sessions(id,user_id) select id,id from public.profiles where id::text like '40000000-%';
update private.authz set role='critic' where user_id in ('40000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000005');
update private.authz set role='moderator' where user_id='40000000-0000-0000-0000-000000000003';
update private.authz set role='admin' where user_id='40000000-0000-0000-0000-000000000004';
insert into public.manual_games(id,title,synopsis,platforms,genres,source_url,source_label) values('40000000-0000-0000-0000-000000000099','Isolated critical SQL fixture','Isolated SQL fixture only, never provider evidence.',array['PC'],array['Plataformas'],'https://example.com/isolated-critical-sql','Isolated test');
create function pg_temp.critical_op(n integer, action text, input jsonb default null, version integer default null) returns jsonb language sql as $$select private.review_operation(('40000000-0000-0000-0000-00000000000'||n)::uuid,('40000000-0000-0000-0000-00000000000'||n)::uuid,action,'manual:40000000-0000-0000-0000-000000000099',version,input)$$;
insert into public.games(id,provider,external_id,document) values('rawg:4000000000099','rawg',4000000000099,'{"title":"Isolated critical genre contract fixture","genres":["action","adventure","rpg","strategy","platformer","puzzle","shooter","racing","sports","simulation","indie"],"platforms":["PC"]}');
select is((select count(*)::int from private.critic_selected_questions('rawg:4000000000099')),12,'server caps broad genre selection at twelve');
update public.games set document=jsonb_set(document,'{genres}','["Unrecognized test genre"]') where id='rawg:4000000000099';
select is((select count(*)::int from private.critic_selected_questions('rawg:4000000000099')),2,'unrecognized authoritative genre falls back to general questions');
-- A newer version only supersedes versions applicable to this game's authoritative genres.
insert into public.critic_questions(question_key,version,genre,prompt,position) values('platformer',2,'strategy','Pregunta estratégica que no corresponde al juego de plataformas.',7);
select is((select version from private.critic_selected_questions('manual:40000000-0000-0000-0000-000000000099') where question_key='platformer'),1,'inapplicable new genre does not suppress the earlier applicable version');
insert into public.manual_games(id,title,synopsis,platforms,genres,source_url,source_label) values('4abcdef0-abcd-4abc-abcd-abcdef012399','Isolated uppercase UUID fixture','Isolated manual fixture with alphabetic UUID digits.',array['PC'],array['Plataformas'],'https://example.com/isolated-critical-uppercase','Isolated test');
select is((select count(*)::int from private.critic_selected_questions('manual:4ABCDEF0-ABCD-4ABC-ABCD-ABCDEF012399')),3,'uppercase manual UUID selects its authoritative genre questions');
select is(jsonb_array_length(private.review_operation('40000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','questions','manual:4ABCDEF0-ABCD-4ABC-ABCD-ABCDEF012399')->'questions'),3,'operation accepts uppercase manual UUID and keeps genre-specific selection');
create temp table critical_test_input(data jsonb);
insert into critical_test_input select jsonb_build_object('rating',10,'title','Crítica SQL','bodyPublic','Una valoración original y detallada de esta experiencia.','bodySpoiler','Desenlace oculto','critical',jsonb_build_object('criteria',(select jsonb_object_agg(k,jsonb_build_object('score',i,'explanation','Una explicación propia para este criterio.')) from unnest(array['gameplay','narrative','art','sound','performance','accessibility','content','value']) with ordinality as x(k,i)),'platform','PC','hoursPlayed',20.5,'completed',true,'copyProvided',false,'scoreReason','Una justificación editorial suficientemente extensa.','answers',(select jsonb_agg(jsonb_build_object('questionId',id,'answer','Respuesta editorial propia.')) from private.critic_selected_questions('manual:40000000-0000-0000-0000-000000000099'))));
select is(private.critical_score(jsonb_set((select data->'critical' from critical_test_input),'{criteria}',(select jsonb_object_agg(k,jsonb_build_object('score',case when k='value' then 2.04 else 2 end,'explanation','Explicación válida para redondeo.')) from unnest(array['gameplay','narrative','art','sound','performance','accessibility','content','value']) k))),2.01::numeric,'exact decimal mean half rounds upward');
select is((select count(*)::int from private.critic_selected_questions('manual:40000000-0000-0000-0000-000000000099')),3,'authoritative Spanish genre selects general plus platformer');
select throws_ok($$select pg_temp.critical_op(2,'create',data) from critical_test_input$$,'42501',null,'user cannot create critical format');
select throws_ok($$select pg_temp.critical_op(3,'create',data) from critical_test_input$$,'42501',null,'moderator cannot author');
select throws_ok($$select pg_temp.critical_op(4,'create',data) from critical_test_input$$,'42501',null,'admin cannot author');
select throws_ok($$select pg_temp.critical_op(1,'create',jsonb_set(data,'{critical,criteria,art,score}','11')) from critical_test_input$$,'22023',null,'criterion outside range');
select throws_ok($$select pg_temp.critical_op(1,'create',jsonb_set(data,'{critical,criteria,art,score}','1.001')) from critical_test_input$$,'22023',null,'criterion precision');
select throws_ok($$select pg_temp.critical_op(1,'create',data#-'{critical,criteria,art}') from critical_test_input$$,'22023',null,'missing criterion');
select throws_ok($$select pg_temp.critical_op(1,'create',jsonb_set(data,'{critical,platform}','"Xbox"')) from critical_test_input$$,'22023',null,'platform must belong to real game');
select throws_ok($$select pg_temp.critical_op(1,'create',jsonb_set(data,'{critical,answers}','[]')) from critical_test_input$$,'22023',null,'selected answers required');
select is((select count(*)::int from public.reviews where author_id::text like '40000000-%'),0,'invalid writes leave no rows');
select lives_ok($$select pg_temp.critical_op(1,'create',data) from critical_test_input$$,'unverified critic publishes');
select is((select rating from public.reviews where author_id='40000000-0000-0000-0000-000000000001'),4.50::numeric,'server mean overrides client ten');
select is((select kind from public.reviews where author_id='40000000-0000-0000-0000-000000000001'),'critic','critical kind persists');
select is((select critic_verified from public.reviews where author_id='40000000-0000-0000-0000-000000000001'),false,'critic role never invents verification');
select throws_ok($$select pg_temp.critical_op(1,'create',data) from critical_test_input$$,'23505',null,'critical occupies same uniqueness');
select throws_ok($$select pg_temp.critical_op(1,'update',jsonb_set(data,'{critical,criteria,art,score}','9'),1) from critical_test_input$$,'22023',null,'mean change needs distinct public opinion');
select throws_ok($$select pg_temp.critical_op(1,'update',data,9) from critical_test_input$$,'40001',null,'critical optimistic version');
-- Publishing a new bank version must not reinterpret already persisted answers.
insert into public.critic_questions(question_key,version,genre,prompt,position) values('experience',2,'*','¿Qué identidad tiene esta nueva pregunta editorial?',1);
select throws_ok($$update public.critic_questions set prompt='Texto reescrito que no debe poder reemplazar su versión.' where question_key='experience' and version=1$$,'22023',null,'old question text is immutable');
select lives_ok($$select pg_temp.critical_op(1,'update',data,1) from critical_test_input$$,'old question set editable after bank version changes');
select is((pg_temp.critical_op(1,'own')->'critical'->'answers'->0->'question'->>'version'),'1','historical question version remains one');
-- Catalog changes must allow the unchanged historical platform while rejecting new unknown values.
update public.manual_games set platforms=array['Nintendo'] where id='40000000-0000-0000-0000-000000000099';
select lives_ok($$select pg_temp.critical_op(1,'update',data,2) from critical_test_input$$,'unchanged historical platform remains editable after catalog changes');
select throws_ok($$select pg_temp.critical_op(1,'update',jsonb_set(data,'{critical,platform}','"Xbox"'),3) from critical_test_input$$,'22023',null,'new platform must still belong to current catalog');
update public.manual_games set platforms=array['PC'] where id='40000000-0000-0000-0000-000000000099';
-- Roll back only the successful test's version bump to leave the remainder of the original flow unchanged.
update public.reviews set version=2 where author_id='40000000-0000-0000-0000-000000000001';
-- Capture identities before API RLS can hide parents; child probes use only these known IDs.
create temp table critical_public_ids as select id from public.reviews where author_id='40000000-0000-0000-0000-000000000001';
grant select on critical_public_ids to anon,authenticated;
set local role anon;
select is((select count(*)::int from public.review_critic_details where review_id in(select id from pg_temp.critical_public_ids)),1,'anon sees published details by known ID');
select is((select count(*)::int from public.review_critic_answers where review_id in(select id from pg_temp.critical_public_ids)),3,'anon sees published answers by known ID');
reset role;
set local role authenticated;
select is((select count(*)::int from public.review_critic_details where review_id in(select id from pg_temp.critical_public_ids)),1,'authenticated sees published details by known ID');
select is((select count(*)::int from public.review_critic_answers where review_id in(select id from pg_temp.critical_public_ids)),3,'authenticated sees published answers by known ID');
reset role;
update private.authz set role='user' where user_id='40000000-0000-0000-0000-000000000001';
select throws_ok($$select pg_temp.critical_op(1,'update',data,2) from critical_test_input$$,'42501',null,'former critic cannot write critical details');
select lives_ok($$select pg_temp.critical_op(1,'update',(data-'critical')||'{"rating":10,"bodyPublic":"Una nueva opinión básica del mismo análisis histórico."}',2) from critical_test_input$$,'former critic can edit basic public text');
select is((select rating from public.reviews where author_id='40000000-0000-0000-0000-000000000001'),4.50::numeric,'former critic cannot replace calculated note');
select is((select kind from public.reviews where author_id='40000000-0000-0000-0000-000000000001'),'critic','demotion retains historic kind');
select lives_ok($$select pg_temp.critical_op(1,'withdraw',null,3)$$,'former critic withdraws');
set local role anon;
select is((select count(*)::int from public.review_critic_details where review_id in(select id from pg_temp.critical_public_ids)),0,'withdrawn critical details inaccessible');
select is((select count(*)::int from public.review_critic_answers where review_id in(select id from pg_temp.critical_public_ids)),0,'withdrawn answers inaccessible');
select ok((select count(*)>0 from public.critic_questions),'question bank public');
select throws_ok($$insert into public.review_critic_details(review_id) values(gen_random_uuid())$$,'42501',null,'anon cannot insert details');
select throws_ok($$update public.review_critic_answers set answer='forged'$$,'42501',null,'anon cannot update answers');
select throws_ok($$delete from public.critic_questions$$,'42501',null,'anon cannot mutate bank');
reset role;
set local role authenticated;
select is((select count(*)::int from public.review_critic_details where review_id in(select id from pg_temp.critical_public_ids)),0,'authenticated cannot see withdrawn details by known ID');
select is((select count(*)::int from public.review_critic_answers where review_id in(select id from pg_temp.critical_public_ids)),0,'authenticated cannot see withdrawn answers by known ID');
reset role;
select lives_ok($$select pg_temp.critical_op(1,'republish',null,4)$$,'former critic republishes same review');
-- Ordinary reviews remain ordinary on promotion; conversion requires an explicit action.
select lives_ok($$select pg_temp.critical_op(2,'create',data-'critical') from critical_test_input$$,'ordinary user publishes');
select throws_ok($$select pg_temp.critical_op(2,'convert',data-'critical',1) from critical_test_input$$,'42501',null,'DB denies conversion without critic role even if details absent');
update private.authz set role='critic' where user_id='40000000-0000-0000-0000-000000000002';
select is((select kind from public.reviews where author_id='40000000-0000-0000-0000-000000000002'),'user','promotion retains ordinary kind');
select lives_ok($$select pg_temp.critical_op(2,'update',data-'critical',1) from critical_test_input$$,'critic can maintain ordinary review');
select lives_ok($$select pg_temp.critical_op(2,'withdraw',null,2)$$,'withdraw before conversion');
create temp table original_identity as select id from public.reviews where author_id='40000000-0000-0000-0000-000000000002';
update critical_test_input set data=jsonb_set(jsonb_set(data,'{critical,answers}',(select jsonb_agg(jsonb_build_object('questionId',id,'answer','Nueva respuesta propia.')) from private.critic_selected_questions('manual:40000000-0000-0000-0000-000000000099'))),'{bodyPublic}','"Una opinión pública nueva que acompaña una nota calculada distinta."');
select lives_ok($$select pg_temp.critical_op(2,'convert',data,3) from critical_test_input$$,'explicit conversion accepts current bank');
select is((select id from public.reviews where author_id='40000000-0000-0000-0000-000000000002'),(select id from original_identity),'conversion retains same ID');
select is((select status from public.reviews where author_id='40000000-0000-0000-0000-000000000002'),'withdrawn','conversion retains withdrawal');
select is((select count(*)::int from public.reviews where author_id='40000000-0000-0000-0000-000000000002'),1,'conversion never duplicates');
update private.authz set status='suspended' where user_id='40000000-0000-0000-0000-000000000001';
set local role anon;
select is((select count(*)::int from public.review_critic_details where review_id in(select id from pg_temp.critical_public_ids)),0,'anon cannot see suspended details by known ID');
select is((select count(*)::int from public.review_critic_answers where review_id in(select id from pg_temp.critical_public_ids)),0,'anon cannot see suspended answers by known ID');
reset role;
set local role authenticated;
select is((select count(*)::int from public.review_critic_details where review_id in(select id from pg_temp.critical_public_ids)),0,'suspended and withdrawn details hidden from all API accounts');
select is((select count(*)::int from public.review_critic_answers where review_id in(select id from pg_temp.critical_public_ids)),0,'suspended answers hidden');
select throws_ok($$update public.review_critic_details set platform='forged'$$,'42501',null,'authenticated cannot update details');
select throws_ok($$delete from public.review_critic_answers$$,'42501',null,'authenticated cannot delete answers');
select throws_ok($$select private.critical_score('{}')$$,'42501',null,'private helper not API executable');
reset role;
select throws_ok($$select pg_temp.critical_op(1,'own')$$,'42501',null,'suspended own private read denied');
create function pg_temp.fail_critical_audit() returns trigger language plpgsql as $$begin raise exception 'Isolated critical audit failure'; end;$$;
create trigger isolated_critical_audit_fault before insert on private.audit_logs for each row execute function pg_temp.fail_critical_audit();
select throws_ok($$select pg_temp.critical_op(5,'create',data) from critical_test_input$$,'P0001',null,'critical audit failure aborts parent and children');
select is((select count(*)::int from public.reviews where author_id='40000000-0000-0000-0000-000000000005'),0,'audit failure leaves no parent');
select is((select count(*)::int from public.review_critic_details where review_id in(select id from public.reviews where author_id::text like '40000000-%')),2,'audit failure leaves only previously saved details');
drop trigger isolated_critical_audit_fault on private.audit_logs;
set local role service_role;
select throws_ok($$update public.review_critic_details set platform='forged'$$,'42501',null,'service role has no details write grant');
select throws_ok($$delete from public.critic_questions$$,'42501',null,'service role has no bank write grant');
reset role;
select * from finish();
rollback;
